if (!isSourceFile(rel, loadExtensionOverrides(this.projectRoot))) {
  // A deleted directory arrives as a bare directory event; its child
  // files must be reconciled out of the index by a sync.
  const abs = path.join(this.projectRoot, rel);
  if (!fs.existsSync(abs)) {
    for (const d of [...this.dirWatchers.keys()]) {
      if (d === abs || d.startsWith(abs + path.sep)) this.unwatchDir(d);
    }
    logDebug('Path removed, scheduling sync', { file: rel });
    this.scheduleSync();
  }
  return;
